// Мапа емодзі без селектора варіативності (U+FE0F)
const _EMOJI_NORM = {};
for (const k of Object.keys(ICON_PATHS)) {
  _EMOJI_NORM[k.replace(/\uFE0F/g, '')] = k;
}

// Регулярний вираз для пошуку будь-якого відомого емодзі у тексті
// (необов'язковий U+FE0F споживається разом з емодзі)
const _EMOJI_SRC = "🚀\\uFE0F?|💼\\uFE0F?|📦\\uFE0F?|📂\\uFE0F?|📥\\uFE0F?|📤\\uFE0F?|ℹ\\uFE0F?|❌\\uFE0F?|🚪\\uFE0F?|📄\\uFE0F?|🔍\\uFE0F?|🔎\\uFE0F?|📝\\uFE0F?|📑\\uFE0F?|✍\\uFE0F?|⚙\\uFE0F?|📚\\uFE0F?|🔑\\uFE0F?|📌\\uFE0F?|🛟\\uFE0F?|✂\\uFE0F?|✚\\uFE0F?|✓\\uFE0F?|✗\\uFE0F?|✕\\uFE0F?|➕\\uFE0F?|➖\\uFE0F?|💾\\uFE0F?|🗑\\uFE0F?|✅\\uFE0F?|🎨\\uFE0F?|📐\\uFE0F?|🖼\\uFE0F?|📎\\uFE0F?|📷\\uFE0F?|🔗\\uFE0F?|🧩\\uFE0F?|🚩\\uFE0F?|🖨\\uFE0F?|📋\\uFE0F?|🔒\\uFE0F?|🔓\\uFE0F?|👁\\uFE0F?|▶\\uFE0F?|◀\\uFE0F?|⏮\\uFE0F?|⏭\\uFE0F?|✏\\uFE0F?|▼\\uFE0F?|▲\\uFE0F?|◂\\uFE0F?|▸\\uFE0F?|⤢\\uFE0F?|🔄\\uFE0F?|↕\\uFE0F?|🔬\\uFE0F?|📊\\uFE0F?|⚡\\uFE0F?|👍\\uFE0F?|👎\\uFE0F?|❓\\uFE0F?|😉\\uFE0F?|🛢\\uFE0F?|📅\\uFE0F?|⬇\\uFE0F?|⚠\\uFE0F?|🔽\\uFE0F?|🗂\\uFE0F?|🛠\\uFE0F?|👆\\uFE0F?|🔤\\uFE0F?|𝄜\\uFE0F?";
const _EMOJI_RE = new RegExp(_EMOJI_SRC, 'gu');

const LANG_FLAGS = {
  uk: 'ua', en: 'gb', pl: 'pl', de: 'de', fr: 'fr', es: 'es', it: 'it'
};

// Повертає inline SVG-розмітку для емодзі або null
function getIconSvg(emoji) {
  const norm = _EMOJI_NORM[(emoji || '').replace(/\uFE0F/g, '')];
  const body = norm ? ICON_PATHS[norm] : undefined;
  if (!body) return null;
  return '<svg xmlns="http://www.w3.org/2000/svg" width="1em" height="1em" viewBox="0 0 36 36" aria-hidden="true">' + body + '</svg>';
}

// Повертає inline SVG прапора за кодом мови або null
function getFlagSvg(langCode) {
  const code = LANG_FLAGS[langCode];
  const svg = code && FLAG_SVGS[code];
  if (!svg) return null;
  return '<span class="flag-icon">' + svg + '</span>';
}

// Встановити вміст .ui-icon: SVG замість емодзі
// Використовується i18n.js при створенні елементів іконок.
function setIconContent(el, emoji) {
  const svg = getIconSvg(emoji);
  if (!svg) {
    el.textContent = emoji;
    return false;
  }
  el.dataset.icon = emoji;
  el.classList.add('svg-icon');
  el.innerHTML = svg;
  return true;
}

// Отримати "текущий" емодзі з .ui-icon (для перекладу):
// раніше зчитували textContent, тепер зчитуємо data-icon.
function getExistingIcon(el) {
  const found = el.querySelector(':scope > .ui-icon');
  return found ? (found.dataset.icon || '') : '';
}

// Конвертує один текстовий вузол: помічені емодзі → inline SVG
function convertTextNode(textNode) {
  if (!textNode || !textNode.nodeValue) return;
  const text = textNode.nodeValue;
  if (!_EMOJI_RE.test(text)) { _EMOJI_RE.lastIndex = 0; return; }
  _EMOJI_RE.lastIndex = 0;

  const parent = textNode.parentElement;
  if (!parent) return;
  const tag = parent.tagName;
  if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'OPTION') return;

  // Вже існуючий .ui-icon: конвертуємо всередину, не обгортаючи ще раз
  if (parent.classList && parent.classList.contains('ui-icon')) {
    const trimmed = text.trim();
    const svg = getIconSvg(trimmed);
    if (svg) {
      parent.dataset.icon = trimmed;
      parent.classList.add('svg-icon');
      parent.innerHTML = svg;
    }
    return;
  }

  const matches = [];
  let m;
  while ((m = _EMOJI_RE.exec(text)) !== null) {
    const emoji = m[0];
    const svg = getIconSvg(emoji);
    if (!svg) continue;
    matches.push({ start: m.index, end: m.index + m[0].length, emoji, svg });
  }
  if (!matches.length) return;

  const frag = document.createDocumentFragment();
  let lastPos = 0;
  for (const v of matches) {
    if (v.start > lastPos) frag.appendChild(document.createTextNode(text.slice(lastPos, v.start)));
    const span = document.createElement('span');
    span.className = 'ui-icon svg-icon';
    span.dataset.icon = v.emoji;
    span.innerHTML = v.svg;
    frag.appendChild(span);
    lastPos = v.end;
  }
  if (lastPos < text.length) frag.appendChild(document.createTextNode(text.slice(lastPos)));
  parent.replaceChild(frag, textNode);
}

// Обробляє піддерево: конвертує всі текстові вузли з емодзі
function convertEmojiInContainer(root) {
  if (!root || root.nodeType !== Node.ELEMENT_NODE) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      if (!node.nodeValue) return NodeFilter.FILTER_REJECT;
      _EMOJI_RE.lastIndex = 0;
      if (!_EMOJI_RE.test(node.nodeValue)) return NodeFilter.FILTER_REJECT;
      _EMOJI_RE.lastIndex = 0;
      const p = node.parentElement;
      if (!p) return NodeFilter.FILTER_REJECT;
      if (p.tagName === 'SCRIPT' || p.tagName === 'STYLE' || p.tagName === 'TEXTAREA' || p.tagName === 'OPTION') return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });

  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const node of nodes) convertTextNode(node);
}

// Конвертує весь документ
function convertAllIcons() {
  convertEmojiInContainer(document.body);
}

// Спостерігач: конвертує емодзі в щойно доданих/змінених вузлах
let _iconObserver = null;
let _iconTimer = null;

function _scheduleIconConversion() {
  clearTimeout(_iconTimer);
  _iconTimer = setTimeout(convertAllIcons, 25);
}

function initIconObserver() {
  if (_iconObserver) return;
  _iconObserver = new MutationObserver(mutations => {
    for (const mutation of mutations) {
      if (mutation.type === 'characterData') {
        _scheduleIconConversion();
        return;
      }
      for (const added of mutation.addedNodes) {
        if (added.nodeType === Node.ELEMENT_NODE) {
          _scheduleIconConversion();
          return;
        }
        if (added.nodeType === Node.TEXT_NODE && added.nodeValue && _EMOJI_RE.test(added.nodeValue)) {
          _scheduleIconConversion();
          return;
        }
      }
    }
  });
  _iconObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
}

function initIcons() {
  if (document.body) {
    convertAllIcons();
    initIconObserver();
  } else {
    document.addEventListener('DOMContentLoaded', () => {
      convertAllIcons();
      initIconObserver();
    });
  }
}

// ==== Експорт для інших модулів ====
window.getIconSvg = getIconSvg;
window.getFlagSvg = getFlagSvg;
window.setIconContent = setIconContent;
window.getExistingIcon = getExistingIcon;
window.convertTextNode = convertTextNode;
window.convertEmojiInContainer = convertEmojiInContainer;
window.convertAllIcons = convertAllIcons;
window.initIcons = initIcons;
window.ICON_PATHS = ICON_PATHS;
window.FLAG_SVGS = FLAG_SVGS;
window.LANG_FLAGS = LANG_FLAGS;
window._EMOJI_RE = _EMOJI_RE;

// Автоініціалізація (після готовності DOM)
if (typeof document !== 'undefined') {
  initIcons();
}
